// Вузол Code: формує запит до Groq (system + few-shot + CoT, T=0, json_object)
const MODEL = 'qwen/qwen3.8-27b'; // <- замініть на модель, яка спрацювала в ноутбуці (змінна MODEL)
const ocrText = $input.first().json.ocr_text;

const schemaHint = {
  reasoning: 'string - Chain-of-Thought: виправлення OCR, групування позицій, звірка суми',
  merchant_name: 'string | null',
  date: 'string YYYY-MM-DD | null',
  items: [{ name: 'string', quantity: 'number', price: 'number | null', total: 'number | null' }],
  total_amount: 'number | null'
};

const system =
  'Ти - експертний автономний модуль інтелектуального вилучення даних з документів. ' +
  'Тобі надано сирий текст чека після OCR. Виправ шуми розпізнавання, згрупуй товари з цінами ' +
  'та поверни СТРОГО валідний JSON за схемою: ' + JSON.stringify(schemaHint) + '. ' +
  'ВИМОГИ: поверни ТІЛЬКИ чистий JSON-об\'єкт без маркдаун-тегів; обов\'язково заповни поле reasoning ' +
  '(хід думок і звірка цін); використовуй точні ключі: reasoning, merchant_name, date, items, total_amount; ' +
  'якщо значення неможливо надійно відновити - став null, НЕ вигадуй дані.\n\n' +
  'ПРИКЛАД:\nТекст: \'ATB-Markt 12.05.2025 HLIB 24.00 MOLOKO 36.00 SUMA: 60.00\'\n' +
  'Відповідь: {"reasoning":"Виправлено назву на ATB-Market; дата 2025-05-12; 24+36=60 відповідає підсумку 60.",' +
  '"merchant_name":"ATB-Market","date":"2025-05-12",' +
  '"items":[{"name":"HLIB","quantity":1.0,"price":24.0,"total":24.0},{"name":"MOLOKO","quantity":1.0,"price":36.0,"total":36.0}],' +
  '"total_amount":60.0}';

return [{
  json: {
    ocr_text: ocrText,
    body: {
      model: MODEL,
      temperature: 0,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: '=== OCR-ТЕКСТ ЧЕКА ===\n' + ocrText }
      ]
    }
  }
}];

// Вузол Code: парсинг відповіді LLM + детермінована арифметична валідація
const resp = $input.first().json;
const ocrText = $('Build Groq Request').first().json.ocr_text;
const raw = resp?.choices?.[0]?.message?.content ?? '';

let data = null, parseError = null;
try {
  let t = String(raw).replace(/<think>[\s\S]*?<\/think>/g, '').trim();
  t = t.replace(/^```(?:json)?\s*|\s*```$/g, '').trim();
  const a = t.indexOf('{'), b = t.lastIndexOf('}');
  if (a === -1 || b === -1) throw new Error('JSON-об\'єкт не знайдено у відповіді');
  data = JSON.parse(t.slice(a, b + 1));
} catch (e) {
  parseError = e.message;
}

const issues = [];
let calcSum = 0, docTotal = 0, merchant = null, date = null, reasoning = '', items = [];
if (data) {
  merchant = data.merchant_name ?? null;
  date = data.date ?? null;
  reasoning = data.reasoning ?? '';
  items = Array.isArray(data.items) ? data.items : [];
  for (const it of items) {
    let t = it.total;
    if ((t === null || t === undefined) && typeof it.price === 'number') t = it.price * (it.quantity ?? 1);
    if (typeof t === 'number') calcSum += t; else issues.push('позиція «' + it.name + '» без суми');
  }
  docTotal = (typeof data.total_amount === 'number' && data.total_amount > 0) ? data.total_amount : 0;
  if (!merchant) issues.push('не визначено назву торгової точки');
  if (items.length === 0) issues.push('список позицій порожній');
  if (docTotal === 0) issues.push('не визначено підсумкову суму (TOTAL)');
  if (docTotal > 0 && items.length > 0 && Math.abs(calcSum - docTotal) > 0.05) {
    issues.push('сума позицій ' + calcSum.toFixed(2) + ' не збігається з TOTAL ' + docTotal.toFixed(2));
  }
} else {
  issues.push('відповідь LLM не є валідним JSON: ' + parseError);
}
const discrepancy = Math.round(Math.abs(calcSum - docTotal) * 100) / 100;

return [{
  json: {
    is_valid: issues.length === 0,
    merchant_name: merchant,
    date,
    total_amount: docTotal,
    calc_sum: Math.round(calcSum * 100) / 100,
    discrepancy,
    items_count: items.length,
    issues: issues.join('; '),
    reasoning,
    raw_response: String(raw).slice(0, 1500),
    ocr_text: ocrText
  }
}];

